{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Ethinylestradiol absolute oral bioavailability was 62 ± 10% (range 41–76%) at 30 µg in 9 subjects, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ofloxacin absolute oral bioavailability was 91% (lower 95% CI 74.1%) versus intravenous administration, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Meptazinol absolute oral bioavailability was 8.7 ± 1.6% after a 200 mg oral dose versus 25 mg i.v., below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer direct absolute oral bioavailability measurements in humans support F ≥20%, including ethinylestradiol, ofloxacin, norethisterone, codeine, melperone, and meperidine. Two low-F molecules, meptazinol and pentazocine, provide contradictory evidence but are outweighed by the consistent high-F evidence.",
  "evidence_gaps": [
    "Praziquantel evidence comes from patients with hepatic cirrhosis/splenomegaly, limiting ordinary-condition transferability.",
    "Thalidomide bioavailability is supported partly by qualitative or estimated reports rather than a single absolute measurement.",
    "Pentazocine healthy-subject values span 11–32%, with a mean near 18%, so threshold classification depends on mean versus individual extremes."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

